<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pageTitle='Audit log';$basePath='../';$rows=$pdo->query('SELECT a.*,u.name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 250')->fetchAll();require __DIR__.'/../includes/layout_top.php';?><div class="panel"><h3>Recent administrative activity</h3><div class="table-wrap"><table><thead><tr><th>When</th><th>Account</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['name']??'System')?></td><td><?=e($r['action'])?></td><td><?=e($r['details'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4" class="empty">No activity logged yet.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
